input.command:
python3 -I - <<'EOF'
import json
d=json.load(open('cases.json',encoding='utf-8'))
for c in d['cases']:
    if c['name']=='definition inside procedure':
        c['source']='oto a\noto b\n  np 10\njuż'
        c['expect']={'error':{'line':2,'column':1}}
json.dump(d,open('cases.json','w',encoding='utf-8'),ensure_ascii=False,indent=1)
# final validation
d=json.load(open('cases.json',encoding='utf-8'))
assert d['version']==1
for c in d['cases']:
    assert set(c)=={'name','mode','source','expect'} and c['mode'] in ('2d','3d')
    e=c['expect']; assert 'segments' in e or 'error' in e
    for s in e.get('segments',[]):
        assert set(s)=={'from','to','color','width'} and len(s['from'])==3 and len(s['to'])==3
        assert s['color']==s['color'].lower() and isinstance(s['width'],int)
    if 'error' in e:
        ln=e['error']['line']; lines=c['source'].split('\n'); assert 1<=ln<=len(lines)
        if 'column' in e['error']: assert 1<=e['error']['column']<=len(lines[ln-1])
print('valid', len(d['cases']), 'cases')
EOF

